92	// Store persists heartbeats as per-node JSON files under a data directory.
93	// Multiple Store instances (in the same or different processes) may safely
94	// access the same directory concurrently: a flock on the directory lock file
95	// serialises writers and lets queries take a shared lock, so a query never
96	// observes a partially written batch.
97	//
98	// Node files live in two places chosen solely by the byte length of the node
99	// id:
100	//
101	//   - Short ids keep their file at nodes/hex(nodeID)+".json", exactly as
102	//     always; the file name itself decodes to the owning node id.
103	//   - Long ids (those whose hex name would exceed the local file-name limit)
104	//     keep their file at slots/<sha256(nodeID)>.json: a fixed-length content
105	//     name that never grows with the id. The hash is computed over the whole
106	//     id and only addresses the file — it never identifies the node — so a
107	//     slot is loaded for a specific queried id and every record in it must
108	//     declare that same id, the same ownership check a named hex file gets.
109	//     A different id whose well-formed file is found at this slot (a planted
110	//     foreign file) is refused as corruption rather than merged or read as
111	//     this node's telemetry.
112	type Store struct {
113		dir      string
114		nodesDir string
115		slotsDir string
116		lockPath string
117	}
118	
119	// OpenStore opens (and if needed creates) a data directory.
120	func OpenStore(dir string) (*Store, error) {
121		if err := os.MkdirAll(dir, 0o755); err != nil {
122			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
123		}
124		nodesDir := filepath.Join(dir, "nodes")
125		if err := os.MkdirAll(nodesDir, 0o755); err != nil {
126			return nil, fmt.Errorf("cannot create nodes directory %s: %w", nodesDir, err)
127		}
128		slotsDir := filepath.Join(dir, "slots")
129		if err := os.MkdirAll(slotsDir, 0o755); err != nil {
130			return nil, fmt.Errorf("cannot create slots directory %s: %w", slotsDir, err)
131		}
132		return &Store{
133			dir:      dir,
134			nodesDir: nodesDir,
135			slotsDir: slotsDir,
136			lockPath: filepath.Join(dir, "lock"),
137		}, nil
138	}
