160	// nodeLocationFor maps a node id to its storage location. The mapping depends
161	// only on the exact id bytes — no trimming, whitespace handling or character
162	// replacement — so two ids are stored apart unless their bytes are identical:
163	// ids sharing a long prefix and differing at the end hash differently, and an
164	// id submitted literally or via equivalent JSON escapes decodes to the same
165	// bytes and maps to the same file. A short id's file name is its own hex,
166	// which reversibly carries its owner; a long id's slot name is the full hash
167	// of its bytes and carries no id text at all, so its owner is the queried id
168	// itself.
169	func (s *Store) nodeLocationFor(nodeID string) nodeLocation {
170		raw := []byte(nodeID)
171		hexName := hex.EncodeToString(raw) + ".json"
172		if len(hexName) <= maxNodeFileNameBytes {
173			return nodeLocation{
174				path:  filepath.Join(s.nodesDir, hexName),
175				owner: nodeID,
176				named: true,
177			}
178		}
179		sum := sha256.Sum256(raw)
180		return nodeLocation{
181			path:  filepath.Join(s.slotsDir, hex.EncodeToString(sum[:])+".json"),
