package edgefleet

import (
	"strings"
	"testing"
	"time"
)

// Submit boundary: duplicate name is reported before its (invalid) value is read.
func TestProbeHeartbeatDupBeforeValue(t *testing.T) {
	_, err := ParseHeartbeats([]byte(`[{"node":"a","node":!,"seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1","height":0,"missed":0}]`), time.Now())
	if err == nil || !strings.Contains(err.Error(), `duplicate field "node"`) {
		t.Fatalf("want duplicate field node, got %v", err)
	}
}

// Submit boundary: missing required beats unknown field.
func TestProbeHeartbeatMissingBeforeUnknown(t *testing.T) {
	_, err := ParseHeartbeats([]byte(`[{"node":"a","extra":1}]`), time.Now())
	if err == nil || !strings.Contains(err.Error(), `missing required field "seq"`) {
		t.Fatalf("want missing required field seq, got %v", err)
	}
}

// Envelope boundary: value decode error beats the duplicate check for the same key.
func TestProbeEnvelopeValueBeforeDup(t *testing.T) {
	_, err := decodeStrictNodeFile([]byte(`{"format":"x","format":!}`))
	if err == nil || !strings.Contains(err.Error(), `invalid value for envelope field "format"`) {
		t.Fatalf("want invalid value for envelope field format, got %v", err)
	}
}

// Envelope boundary: unknown field is rejected inline, before missing-field checks.
func TestProbeEnvelopeUnknownBeforeMissing(t *testing.T) {
	_, err := decodeStrictNodeFile([]byte(`{"extra":1}`))
	if err == nil || !strings.Contains(err.Error(), `unknown envelope field "extra"`) {
		t.Fatalf("want unknown envelope field extra, got %v", err)
	}
	// and with all required present but unknown first in document order
	_, err = decodeStrictNodeFile([]byte(`{"extra":1,"format":"x"}`))
	if err == nil || !strings.Contains(err.Error(), `unknown envelope field "extra"`) {
		t.Fatalf("want unknown envelope field extra, got %v", err)
	}
}

// Envelope boundary: typed decode of an early key beats a later key's syntax error.
func TestProbeEnvelopeTypedDecodeInline(t *testing.T) {
	_, err := decodeStrictNodeFile([]byte(`{"format":5,"checksum":!}`))
	if err == nil || !strings.Contains(err.Error(), `format must be a string`) {
		t.Fatalf("want format must be a string, got %v", err)
	}
}

// Escaped-only spelling of a required field is recognized; escaped respelling collides.
func TestProbeEscapedFieldNames(t *testing.T) {
	good := `[{"node":"a","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1","height":0,"misséd":0}]`
	recs, err := ParseHeartbeats([]byte(good), time.Now().Add(time.Hour))
	if err != nil || len(recs) != 1 {
		t.Fatalf("escaped-only missed must be accepted: %v", err)
	}
	bad := `[{"node":"a","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1","height":0,"missed":0,"misséd":0}]`
	if _, err := ParseHeartbeats([]byte(bad), time.Now().Add(time.Hour)); err == nil || !strings.Contains(err.Error(), `duplicate field "missed"`) {
		t.Fatalf("escaped respelling must collide: %v", err)
	}
}
